const xml = $input.first().json.data || '';
const re = /<loc>(https:\/\/phutrust\.com\/blog\/[^<]+)<\/loc>/g;
const all = []; let m;
while ((m = re.exec(xml)) !== null) {
  const u = m[1].trim();
  if (u !== 'https://phutrust.com/blog/') all.push(u);
}
const sd = $getWorkflowStaticData('global');
const posted = sd.postedUrls || [];
const newU = all.filter(u => !posted.includes(u));
console.log('New URLs:', newU);
if (newU.length === 0) return [{ json: { hasNew: false, url: '' } }];
return newU.map(u => ({ json: { hasNew: true, url: u } }));

const html = $input.first().json.data || '';
const tm = html.match(/<title[^>]*>([^<]+)<\/title>/i);
const title = tm ? tm[1].replace(/ \| PhuTrust/,'').replace(/ \| .*$/,'').trim() : 'บทความใหม่';
const dm = html.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i) || html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+name=["']description["']/i);
const desc = dm ? dm[1].trim() : '';
const articleUrl = $('Find New Articles').item.json.url;
console.log('Title:', title, 'Desc:', desc);
return [{ json: { title, desc, url: articleUrl } }];

const teaser = $input.first().json.content[0].text.trim();
const art = $('Extract Meta').item.json;
const msg = teaser + '

👉 อ่านต่อ: ' + art.url + '

#ขายฝาก #ขายฝากที่ดิน #ภูเก็ต #PhuTrust';
return [{ json: { message: msg, url: art.url } }];

const url = $('Extract Meta').item.json.url;
const sd = $getWorkflowStaticData('global');
if (!sd.postedUrls) sd.postedUrls = [];
if (!sd.postedUrls.includes(url)) sd.postedUrls.push(url);
console.log('Saved:', url, '| Total:', sd.postedUrls.length);
return [{ json: { success: true, url, fbPostId: $input.first().json.id } }];
